package org.simpleweather.app;
import android.app.*;
import android.widget.*;
import android.view.*;
import org.json.*;
import java.util.*;

public final class AppStoreScreen {
    private final MainActivity a;
    private final LinearLayout owner;
    private LinearLayout list;
    private TextView status;
    public AppStoreScreen(MainActivity a){this.a=a;owner=a.body;}
    private boolean current(){return !a.isFinishing()&&!a.isDestroyed()&&a.body==owner;}
    public void render(){owner.addView(a.text(a.getString(R.string.launcher_store),24,a.TITLE,true));a.gap(owner,14);LinearLayout controls=a.row();controls.addView(a.button(a.getString(R.string.module_catalog_refresh),false,this::refresh),new LinearLayout.LayoutParams(0,-2,1));a.gapHorizontal(controls,8);controls.addView(a.button(a.getString(R.string.module_import_package),false,a.apps::pick),new LinearLayout.LayoutParams(0,-2,1));owner.addView(controls);a.gap(owner,12);status=a.text(a.getString(R.string.module_catalog_local),13,a.MUTED,false);owner.addView(status);a.gap(owner,12);list=a.column();owner.addView(list);try{draw(a.apps.bundledCatalog());}catch(Exception e){status.setText(a.getString(R.string.module_catalog_failed));}a.gap(owner,16);TextParagraphs.append(a,owner,a.getString(R.string.module_store_note),13,a.MUTED);refresh();}
    private void draw(JSONArray entries)throws Exception{list.removeAllViews();Set<String> seen=new HashSet<>();for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i);String id=item.getString("id");if(!(Arrays.asList(AppModules.IDS).contains(id)||Arrays.asList(AppModules.EXTERNAL).contains(id))||!seen.add(id))continue;LinearLayout card=a.column();card.setPadding(a.dp(16),a.dp(16),a.dp(16),a.dp(16));card.setBackground(a.shape(a.WHITE,22));LinearLayout heading=a.row();ImageView icon=new ImageView(a);icon.setImageResource(AppIcons.resource(id));heading.addView(icon,a.lp(48,48));a.gapHorizontal(heading,12);LinearLayout labels=a.column();labels.addView(a.text(a.apps.title(id),18,a.INK,true));a.gap(labels,5);labels.addView(a.text(item.getString("version")+" · "+String.format(Locale.ROOT,"%.0f KiB",item.getLong("bytes")/1024.0),12,a.MUTED,false));heading.addView(labels,new LinearLayout.LayoutParams(0,-2,1));card.addView(heading);a.gap(card,14);boolean installed=a.apps.installed(id);LinearLayout buttons=a.row();TextView install=a.button(a.getString(installed?R.string.module_open:R.string.module_install),!installed,()->{if(installed){if(Arrays.asList(AppModules.EXTERNAL).contains(id))a.apps.openExternal(id);else a.switchTab(Arrays.asList(AppModules.IDS).indexOf(id));}else confirm(item);});buttons.addView(install,new LinearLayout.LayoutParams(0,-2,1));if(installed){a.gapHorizontal(buttons,8);buttons.addView(a.button(a.getString(R.string.module_uninstall),false,()->new LauncherScreen(a).manage(id)),new LinearLayout.LayoutParams(0,-2,1));}card.addView(buttons);list.addView(card);a.gap(list,12);}}
    private void refresh(){if(a.apps.busy)return;status.setText(a.getString(R.string.module_catalog_loading));new Thread(()->{try{JSONArray items=a.apps.remoteCatalog();a.runOnUiThread(()->{if(!current())return;try{draw(items);status.setText(a.getString(R.string.module_catalog_online));}catch(Exception e){status.setText(a.getString(R.string.module_catalog_failed));}});}catch(Exception e){a.runOnUiThread(()->{if(current())status.setText(a.getString(R.string.module_catalog_failed));});}}).start();}
    private void confirm(JSONObject item){String id=item.optString("id");new ToolDialog(a).setTitle(a.apps.title(id)).setMessage(a.getString(Arrays.asList(AppModules.EXTERNAL).contains(id)?R.string.module_external_note:R.string.module_trust_note)).setPositiveButton(a.getString(R.string.module_install),(d,w)->download(item)).setNegativeButton(a.getString(R.string.action_cancel),null).show();}
    private void download(JSONObject item){if(a.apps.busy){a.toast(a.getString(R.string.module_busy));return;}a.apps.busy=true;status.setText(a.getString(R.string.module_downloading));new Thread(()->{try{a.apps.download(item);a.runOnUiThread(()->{a.apps.busy=false;if(Arrays.asList(AppModules.EXTERNAL).contains(item.optString("id")))a.apps.requestExternalInstall();else{a.releaseModule(item.optString("id"));if(current())a.refreshScreen();a.toast(a.getString(R.string.module_installed));}});}catch(Exception e){a.runOnUiThread(()->{a.apps.busy=false;if(current())status.setText(a.getString(R.string.module_download_failed));a.toast(a.getString(R.string.module_install_failed));});}}).start();}
}
